import os,json,cv2,numpy as np
from scipy.ndimage import gaussian_filter,label,distance_transform_edt
from scipy.spatial import cKDTree
from PIL import Image
OUT='/app/output'
lab=np.load(OUT+'/labels.npy')
FIRST=float(os.getenv('FIRST','3.6')); SPACING=float(os.getenv('SPACING','6'))

def resample(a,step=2):
 d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(a,axis=0),axis=1))];u=np.linspace(0,d[-1],max(2,int(np.ceil(d[-1]/step))+1));return np.c_[np.interp(u,d,a[:,0]),np.interp(u,d,a[:,1])]

def make_comp(mask):
 dist=distance_transform_edt(np.pad(mask,1))[1:-1,1:-1]
 loops=[]
 for d in np.arange(FIRST,dist.max()+.01,SPACING):
  cs,_=cv2.findContours(np.uint8(dist>=d),cv2.RETR_LIST,cv2.CHAIN_APPROX_NONE)
  for c in cs:
   a=c[:,0,:].astype(float)
   if len(a)>2:a=cv2.approxPolyDP(a.astype('float32'),.65,True)[:,0,:]
   if len(a)==1:a=np.r_[a,a+[[.1,0]]]
   a=np.r_[a,a[:1]];loops.append(resample(a))
 if not loops:
  y,x=np.unravel_index(dist.argmax(),dist.shape);return [np.array([[x,y],[x+.2,y]])]
 # Connect loops by the shortest valid links. Neighboring offset boundaries have safe straight links.
 trees=[cKDTree(a) for a in loops]; edges=[]
 for i in range(len(loops)):
  for j in range(i):
   ds,ix=trees[j].query(loops[i]);order=np.argsort(ds)
   for ii in order[:min(100,len(order))]:
    jj=ix[ii]; a,b=loops[i][ii],loops[j][jj]
    pts=resample(np.array([a,b]),1);xy=np.round(pts).astype(int)
    if np.min(dist[xy[:,1],xy[:,0]])>=min(FIRST-1,2):
     edges.append((ds[ii],i,j,ii,jj));break
 parent=list(range(len(loops)))
 def root(i):
  while parent[i]!=i:i=parent[i]
  return i
 links=[[] for _ in loops]
 for d,i,j,ii,jj in sorted(edges):
  ri,rj=root(i),root(j)
  if ri!=rj:parent[ri]=rj;links[i].append((ii,j,jj));links[j].append((jj,i,ii))
 seen=set();routes=[]
 def traverse(i,start):
  seen.add(i);a=loops[i]; n=len(a)-1;start=min(start,n-1)
  route=[];linkmap={}
  for ii,j,jj in links[i]:linkmap.setdefault(min(ii,n-1),[]).append((j,jj))
  for t in range(n+1):
   ii=(start+t)%n;route.append(a[ii])
   for j,jj in linkmap.get(ii,[]):
    if j not in seen:
     b=traverse(j,jj);route.extend(b);route.append(a[ii])
  return route
 for i in range(len(loops)):
  if i not in seen:routes.append(np.array(traverse(i,0)))
 return routes

paths=[]
for k in range(10):
 mask=gaussian_filter((lab==k).astype(float),.65)>.5
 cc,n=label(mask); areas=np.bincount(cc.ravel()); count=0
 for j in np.argsort(areas[1:])[::-1]+1:
  if areas[j]<35:continue
  ys,xs=np.where(cc==j);x0,x1=xs.min(),xs.max()+1;y0,y1=ys.min(),ys.max()+1
  m=cc[y0:y1,x0:x1]==j
  routes=make_comp(m)
  for route in routes:
   route+=np.array([x0,y0]);route=resample(route,1.8)
   # pressure selected from clearance for small fragments
   dist=distance_transform_edt(np.pad(m,1))[1:-1,1:-1]
   rr=np.clip(np.round(route-np.array([x0,y0])).astype(int),[0,0],[x1-x0-1,y1-y0-1])
   ds=dist[rr[:,1],rr[:,0]]
   pr=np.where(ds<3, .055, .12)
   paths.append({'color':k,'xy':route.tolist(),'pr':pr.tolist(),'area':int(areas[j])});count+=1
 print(k,count,'paths total',len(paths),flush=True)
json.dump(paths,open(OUT+'/paths.json','w'))
print('total',len(paths),'length px',sum(np.linalg.norm(np.diff(np.array(p['xy']),axis=0),axis=1).sum() for p in paths))
